<script setup lang="ts">import {ref,computed,onMounted} from 'vue';import {networks} from '../stores/networks';import {revisions} from '../stores/revisions';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import CptTable from '../components/CptTable.vue';const selected=ref('demo-revision'),network=ref('demo-network'),name=ref(''),version=ref('r2'),text=ref("[\n  {\n    \"node_id\": \"Fault\",\n    \"parent_values\": [],\n    \"p0\": 0.85,\n    \"p1\": 0.15\n  },\n  {\n    \"node_id\": \"Power\",\n    \"parent_values\": [],\n    \"p0\": 0.92,\n    \"p1\": 0.08\n  },\n  {\n    \"node_id\": \"Heat\",\n    \"parent_values\": [\n      0,\n      0\n    ],\n    \"p0\": 0.95,\n    \"p1\": 0.05\n  },\n  {\n    \"node_id\": \"Heat\",\n    \"parent_values\": [\n      0,\n      1\n    ],\n    \"p0\": 0.55,\n    \"p1\": 0.45\n  },\n  {\n    \"node_id\": \"Heat\",\n    \"parent_values\": [\n      1,\n      0\n    ],\n    \"p0\": 0.25,\n    \"p1\": 0.75\n  },\n  {\n    \"node_id\": \"Heat\",\n    \"parent_values\": [\n      1,\n      1\n    ],\n    \"p0\": 0.09999999999999998,\n    \"p1\": 0.9\n  },\n  {\n    \"node_id\": \"Vibration\",\n    \"parent_values\": [\n      0\n    ],\n    \"p0\": 0.92,\n    \"p1\": 0.08\n  },\n  {\n    \"node_id\": \"Vibration\",\n    \"parent_values\": [\n      1\n    ],\n    \"p0\": 0.19999999999999996,\n    \"p1\": 0.8\n  },\n  {\n    \"node_id\": \"Alarm\",\n    \"parent_values\": [\n      0,\n      0\n    ],\n    \"p0\": 0.98,\n    \"p1\": 0.02\n  },\n  {\n    \"node_id\": \"Alarm\",\n    \"parent_values\": [\n      0,\n      1\n    ],\n    \"p0\": 0.4,\n    \"p1\": 0.6\n  },\n  {\n    \"node_id\": \"Alarm\",\n    \"parent_values\": [\n      1,\n      0\n    ],\n    \"p0\": 0.25,\n    \"p1\": 0.75\n  },\n  {\n    \"node_id\": \"Alarm\",\n    \"parent_values\": [\n      1,\n      1\n    ],\n    \"p0\": 0.050000000000000044,\n    \"p1\": 0.95\n  },\n  {\n    \"node_id\": \"Indicator\",\n    \"parent_values\": [\n      0\n    ],\n    \"p0\": 0.55,\n    \"p1\": 0.45\n  },\n  {\n    \"node_id\": \"Indicator\",\n    \"parent_values\": [\n      1\n    ],\n    \"p0\": 0.44999999999999996,\n    \"p1\": 0.55\n  },\n  {\n    \"node_id\": \"Lock\",\n    \"parent_values\": [\n      0\n    ],\n    \"p0\": 1,\n    \"p1\": 0\n  },\n  {\n    \"node_id\": \"Lock\",\n    \"parent_values\": [\n      1\n    ],\n    \"p0\": 0,\n    \"p1\": 1\n  }\n]");const {error,busy,act}=useTask();onMounted(()=>Promise.all([networks.load(),revisions.load()]));const revision=computed(()=>revisions.items.value.find(r=>r.id===selected.value)),nodes=computed(()=>networks.items.value.find(n=>n.id===revision.value?.network_id)?.nodes||[]);function submit(){act(async()=>{const r=await revisions.create({name:name.value,version:version.value,network_id:network.value,rows_json:text.value});selected.value=r.id;name.value=''})}</script><template><PageHeading index="02 / 概率版本" title="完整父配置，才能解释每一个后验。" note="概率有限且在[0,1]，每个父配置p0+p1=1（容差1e−12）。固定网络/版本号不可覆盖；新修订创建新版本。"/><div class="two-col"><section><label>CPT版本<select v-model="selected"><option v-for="r in revisions.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><template v-if="revision"><h2>{{revision.name}}</h2><CptTable :rows="revision.rows" :nodes="nodes"/><p class="method-note">版本号 {{revision.version}} · 概率Double原值经API可查；严格0与极小正概率分别保留。</p></template></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>创建不可变CPT版本</h2><label>版本名称<input v-model="name" required minlength="2"></label><label>网络<select v-model="network"><option v-for="n in networks.items.value" :key="n.id" :value="n.id">{{n.name}}</option></select></label><label>版本号<input v-model="version" required></label><label>完整CPT行JSON<textarea v-model="text" rows="14" required></textarea></label><Notice :message="error"/><button :disabled="busy">保存概率版本